```yaml
name: Verify CLA in PR Description

on:
  pull_request:
    types: [opened, edited, reopened, synchronize]

permissions:
  pull-requests: read
  contents: read
  issues: write

jobs:
  check-clause:
    runs-on: ubuntu-latest
    steps:
      - name: Verify CLA text in PR body
        uses: actions/github-script@v6
        with:
          github-token: ${{ secrets.GITHUB_TOKEN }}
          script: |
            const prNumber = context.payload.pull_request.number;
            const { data: pr } = await github.rest.pulls.get({
              owner: context.repo.owner,
              repo: context.repo.repo,
              pull_number: prNumber
            });

            const body = pr.body || "";
            const requiredText = "By submitting this pull request, I confirm that you can use, modify, copy, and redistribute this contribution, under the terms of your choice.";

            if (!body.includes(requiredText)) {
              await github.rest.issues.createComment({
                owner: context.repo.owner,
                repo: context.repo.repo,
                issue_number: prNumber,
                body: "❌ **CLA missing** – Please add the required CLA text to the PR description."
              });
              core.setFailed("CLA text missing in PR description.");
            }
